<?php require_once 'includes/functions.php';require_login();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT a.*,q.title,q.allow_retakes FROM attempts a JOIN quizzes q ON q.id=a.quiz_id WHERE a.id=? AND a.user_id=?');$s->execute([$id,user()['id']]);$a=$s->fetch();if(!$a){http_response_code(404);exit('Result not found.');}
$s=db()->prepare('SELECT q.question_text,aa.is_correct,so.option_text selected_answer,co.option_text correct_answer FROM attempt_answers aa JOIN questions q ON q.id=aa.question_id LEFT JOIN options so ON so.id=aa.selected_option_id JOIN options co ON co.question_id=q.id AND co.is_correct=1 WHERE aa.attempt_id=? ORDER BY q.id');$s->execute([$id]);$answers=$s->fetchAll();$pageTitle='Quiz Result';require 'includes/header.php';?>
<section class="hero"><h1><?=e($a['title'])?> Result</h1><div class="stats"><?=$a['percentage']?>%</div><p>You scored <strong><?=$a['score']?> out of <?=$a['total_questions']?></strong>.</p><div class="actions" style="justify-content:center"><a class="button secondary" href="dashboard.php">Dashboard</a><?php if($a['allow_retakes']):?><a class="button" href="instructions.php?id=<?=$a['quiz_id']?>">Retry Quiz</a><?php endif;?></div></section>
<h2>Answer Review</h2><?php foreach($answers as $i=>$x):?><article class="card <?=$x['is_correct']?'correct':'incorrect'?>"><h3><?=($i+1)?>. <?=e($x['question_text'])?></h3><p>Your answer: <strong><?=e($x['selected_answer']??'Not answered')?></strong></p><?php if(!$x['is_correct']):?><p>Correct answer: <strong><?=e($x['correct_answer'])?></strong></p><?php endif;?></article><br><?php endforeach;?>
<?php require 'includes/footer.php';?>
